import React from 'react';

// Ce composant est la réplique du Dashboard Layout (dash1.png)
export default function GendarmerieHome() {
  return (
    <div className="flex h-screen bg-gray-100 font-sans"> {/* Conteneur principal qui prend toute la hauteur */}

      {/* 1. Barre Latérale - (Le grand bloc de navigation) */}
      <aside className="w-64 bg-[#1A202C] text-white flex flex-col p-4 shadow-xl">
        {/* Espace pour le logo / titre */}
        <div className="cursor-pointer mb-8 mt-4">
          <img src="/img/accel_logo_light.png" alt="Logo Accel" className="h-14" />
        </div>
        {/* Zone de navigation */}
        <nav className="flex-1">
          <ul>
            <li className="mb-2">
              <a href="#" className="flex items-center p-2 rounded-lg bg-gray-700/50 transition-colors">
                <span className="mr-3 text-2xl">⚪</span>DASHBOARD
              </a>
            </li>
            <li className="mb-2">
              <a href="#" className="flex items-center p-2 rounded-lg hover:bg-gray-700 transition-colors">
                <span className="mr-3 text-2xl">⚪</span> Événements
              </a>
            </li>
            <li className="mb-2">
              <a href="#" className="flex items-center p-2 rounded-lg hover:bg-gray-700 transition-colors">
                <span className="mr-3 text-2xl">⚪</span> Utilisateurs
              </a>
            </li>
          </ul>
        </nav>
      </aside>

      {/* 2. Contenu Principal - Zone défilante à droite */}
      <div className="flex-1 flex flex-col overflow-hidden">

        {/* 3. En-tête / Barre supérieure - Zone Bleu Foncé (avec l'ondulation) */}
        <div className="h-[220px] bg-[#20264e] relative z-10">
          <header className="flex items-center justify-end p-4 h-full">
            {/* Espace pour la barre de recherche / profil utilisateur */}
            <div className="w-64 h-12 bg-gray-700 rounded-full flex items-center justify-center text-white text-lg mb-4 mr-4">
              Recherche / Profil
            </div>
          </header>

          {/* SVG qui crée la FORME EXACTE de l'ondulation en bas du bloc bleu */}
          <svg
            className="absolute bottom-0 left-0 w-full h-[150px]"
            viewBox="0 0 1000 150"
            preserveAspectRatio="none"
          >
            {/* Le PATH définit la pente descendante et la légère ondulation concave */}
            <path
              fill="#F3F4F6" // Couleur du fond gris clair
              d="M0,70 L250,150 Q350,140 500,150 L1000,150 L1000,0 Z"
            ></path>
          </svg>
        </div>

        {/* 4. Zone de Contenu Défilante - Fond clair */}
        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-100 p-6 pt-0 relative z-20">

          {/* Section des Petites Cartes d'Information (4 cartes) */}
          {/* -mt-[90px] remonte les cartes pour chevaucher l'ondulation */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6 -mt-[90px]">
            {/* Les cartes ont des bordures colorées comme sur le Figma */}
            <div className="bg-white rounded-xl shadow-md p-4 min-h-[140px] border-t-4 border-fuchsia-500">...</div>
            <div className="bg-white rounded-xl shadow-md p-4 min-h-[140px] border-t-4 border-red-500">...</div>
            <div className="bg-white rounded-xl shadow-md p-4 min-h-[140px] border-t-4 border-teal-400">...</div>
            <div className="bg-white rounded-xl shadow-md p-4 min-h-[140px] border-t-4 border-gray-300">...</div>
          </div>

          {/* Section des Grandes Cartes de Contenu */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-6">
            <div className="lg:col-span-2 bg-white rounded-xl shadow-md p-6 min-h-[350px]">Bloc Principal</div>
            <div className="bg-white rounded-xl shadow-md p-6 min-h-[350px]">Bloc Latéral</div>
          </div>

          {/* Section de la Très Grande Carte en Bas */}
          <div className="bg-white rounded-xl shadow-md p-6 min-h-[250px]">Bloc de Pied de Page</div>
        </main>
      </div>
    </div>
  );
}
